package com.smartspend.controller;
import com.smartspend.model.User;import com.smartspend.service.AuthService;import com.smartspend.util.*;import javafx.geometry.*;import javafx.scene.control.*;import javafx.scene.layout.*;import javafx.stage.Stage;
public class LoginView extends BorderPane {private final AuthService auth=new AuthService();private final TextField email=UI.input("Email address");private final PasswordField pass=UI.password("Password");private final Stage stage;private final Runnable register;
 public LoginView(Stage stage,Runnable register){this.stage=stage;this.register=register;setPadding(new Insets(50));getStyleClass().add("auth-bg");VBox box=new VBox(18);box.setMaxWidth(430);box.setAlignment(Pos.CENTER_LEFT);Label logo=new Label("◆ SMARTSPEND");logo.getStyleClass().add("logo");Label h=new Label("Take control of your money.");h.getStyleClass().add("auth-title");Label sub=UI.subtitle("Sign in to your personal finance workspace.");Button login=UI.button("Login");login.setMaxWidth(Double.MAX_VALUE);Label link=new Label("Don't have an account?  Create Account");link.getStyleClass().add("link");link.setOnMouseClicked(e->register.run());login.setOnAction(e->doLogin());pass.setOnAction(e->doLogin());box.getChildren().addAll(logo,h,sub,email,pass,login,link);StackPane center=new StackPane(box);setCenter(center);}
 private void doLogin(){try{User u=auth.login(email.getText(),pass.getText());Session.setUser(u);stage.getScene().setRoot(new MainShell(stage));}catch(Exception e){UI.error(stage,e.getMessage());}}
}
